export const DEVNET_DEFAULTS=Object.freeze({maxCreationFee:'10000000',maxRent:'100000000',unitPrice:'500000',resources:Object.freeze({computeUnitLimit:1400000,loadedAccountsDataSizeLimit:67108864,heapSize:262144,priorityFeeLamports:'0'})});
const views={wallet:['Devnet wallet','Connect one wallet and use its actual test-network assets.'],projects:['Launchpad','Create a material project or launch an existing specimen.'],supplies:['Reagent supply bench','Buy four fixed material classes on Solana Devnet.'],design:['Blueprint terminal','Design and test the actual fixed biological model.'],workshop:['Manufacturing bench','Manufacture an individual component from real material inventory.'],assembly:['Assembly chamber','Validate actual inputs and replace them with their parent.'],energy:['Bioenergy incubator','Register a specimen, settle elapsed chain hours and claim LAB.'],research:['Original research','Private commitment, validation, discovery and winner recognition.'],market:['Living exchange','Trade materials, components, organs and organisms on Devnet.'],assets:['Your specimen shelf','Verified protocol assets from this connected wallet.']};
const labels={wallet:'Wallet',projects:'Launchpad',supplies:'Materials',design:'Design',workshop:'Make',assembly:'Assemble',energy:'Stake & LAB',research:'Research',market:'Market',assets:'Specimens'};
const moduleFor={projects:'launchpad',supplies:'purchase',workshop:'manufacture',assembly:'synthesis',energy:'mining',research:'research',market:'market'};
