 let closed=false,panelOpen=false,view='wallet',snapshot={config:null,state:null,actor:null,busy:false,pending:null},statusText='Verifying Solana Devnet…',statusError=false,flow=null,epoch=0,designer=null,model=null,draftGraph=null,designRevision=0,validated=null,walletController=null,marketPage=null,competition=null,currentBinding='',lastFocus=null;const prefs={primitive:1,profile:4,target:4,challenge:2000000,projectId:null,marketCategory:'ALL',marketMine:false},cleanups=[],saved=[];
