 const currentState=()=>snapshot.state??{works:[],projects:[],materials:[],sources:[],positions:[],wallet:{solLamports:null,labAtoms:null,labMint:null},partial:true};
 const workRows=()=>currentState().works.filter(canReadRow);
 const resources=()=>jsonClone(DEVNET_DEFAULTS.resources);
 const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(cls)e.className=cls;return e;};
 const button=(text,fn,{disabled=false,primary=false,active=false,always=false}={})=>{const b=el('button',text,`lab-op-action${primary?' primary':''}`);b.type='button';b.disabled=disabled||!always&&busy();if(active)b.setAttribute('aria-pressed','true');b.addEventListener('click',()=>{if(b.disabled)return;const clickEpoch=epoch,clickBinding=technicalContext(snapshot);void Promise.resolve().then(()=>{if(!closed&&clickEpoch===epoch&&clickBinding===technicalContext(snapshot))return fn();}).catch(e=>status(labDevnetError(e),true));});return b;};
 const note=text=>el('p',text,'lab-op-note'),row=(...children)=>{const r=el('div',undefined,'lab-op-toolbar');r.append(...children);return r;},card=(title,...children)=>{const c=el('article',undefined,'lab-op-card');c.append(el('h3',title),...children);return c;};
