      if(outcome.transaction?.decision==='CONFIRMED'&&outcome.transaction.businessExecutionVerified===true)continue;if(kind==='research'&&result?.decision==='CRANKER_REQUIRED'&&(snapshot.config?.researchExecutors??[]).some(e=>e.available&&e.address===result.stage?.requiredActor)){status('The authorized verifier is advancing validation. This tab will resume when your author signature is required.');await new Promise(resolve=>setTimeout(resolve,2000));continue;}status(outcome.transaction?'The transaction is still pending. Resume this same workflow after recovery.':decisionText(result));return result;
